def zero_crossings(x):
    return sum(1 for a, b in zip(x, x[1:]) if a * b < 0)

def alarms(x, thr_on, thr_off, need):
    out = []
    run = 0
    active = False
    for i, v in enumerate(x):
        if not active:
            run = run + 1 if v > thr_on else 0
            if run >= need:
                out.append(i)
                active = True
        elif v < thr_off:
            active = False
            run = 0
    return out

