print(alarms(feat, 1.2, 1.0, 1))
print(alarms(feat, 1.2, 1.0, 3))

import math

def bits_per_trial(n, p):
    if p >= 1.0:
        return math.log2(n)
    if p <= 1.0 / n:
        return 0.0
    return math.log2(n) + p * math.log2(p) + (1 - p) * math.log2((1 - p) / (n - 1))

for n, p, t in ((2, 0.90, 2.0), (4, 0.80, 4.0), (8, 0.70, 5.0), (4, 0.25, 4.0)):
    b = bits_per_trial(n, p)
    print(n, p, round(b, 3), round(b * 60 / t, 2))
